/**
 * lib/instanceIdentity.js — LICENSE-ENFORCE LE-2
 *
 * Server-side instance identity. Replaces the old browser-fingerprint
 * heartbeat identity (browser timers are not background jobs — see
 * feedback_no_browser_only_persistence.md) with a persistent server-side
 * UUID that survives restarts via the instance_config table (which lives on
 * the mounted data volume).
 *
 * §11.1 of docs/STREAM_LICENSE_ENFORCE.md: `qi_<uuid>` generated by the auth
 * service on first boot, persisted in instance_config. Restart on the same
 * box never burns an activation seat because the id never changes.
 */

import { randomUUID } from 'crypto';
import { hostname as osHostname } from 'os';

const INSTANCE_ID_KEY = 'instance.id';
const INSTANCE_NAME_KEY = 'instance.name';

function readConfig(db, key) {
    const row = db.prepare('SELECT value FROM instance_config WHERE key = ?').get(key);
    return row?.value || null;
}

function writeConfigIfAbsent(db, key, value, description) {
    // ON CONFLICT DO NOTHING so a race between two callers never clobbers an
    // id that another caller just generated — the first write wins.
    db.prepare(`
        INSERT INTO instance_config (key, value, value_type, description, updated_at)
        VALUES (?, ?, 'string', ?, datetime('now'))
        ON CONFLICT(key) DO NOTHING
    `).run(key, value, description);
}

/**
 * Ensure this instance has a persistent id + name in instance_config,
 * generating and persisting them on first call. Idempotent — safe to call
 * on every boot.
 *
 * @param {import('better-sqlite3').Database} db
 * @returns {{ id: string, name: string }}
 */
export function ensureInstanceId(db) {
    let id = readConfig(db, INSTANCE_ID_KEY);
    if (!id) {
        const candidate = 'qi_' + randomUUID();
        writeConfigIfAbsent(db, INSTANCE_ID_KEY, candidate, 'Persistent server-side instance identity (LICENSE-ENFORCE LE-2)');
        // Re-read in case a concurrent caller generated one first — ON
        // CONFLICT DO NOTHING silently keeps the existing row.
        id = readConfig(db, INSTANCE_ID_KEY) || candidate;
    }

    let name = readConfig(db, INSTANCE_NAME_KEY);
    if (!name) {
        const candidate = osHostname() || 'quoxcore-instance';
        writeConfigIfAbsent(db, INSTANCE_NAME_KEY, candidate, 'Instance display name');
        name = readConfig(db, INSTANCE_NAME_KEY) || candidate;
    }

    return { id, name };
}

/**
 * Read the instance id without generating one. Returns null if boot has
 * never called ensureInstanceId().
 */
export function getInstanceId(db) {
    return readConfig(db, INSTANCE_ID_KEY);
}

/**
 * Read the instance name without generating one.
 */
export function getInstanceName(db) {
    return readConfig(db, INSTANCE_NAME_KEY);
}

export default { ensureInstanceId, getInstanceId, getInstanceName };
